INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 1, 1.5, 0, 110, 0.029, 0, 101, 1, 122601, "仲間と夏を楽しむ、夏海の魔法士。自分を変えたいという固い決意で、障害物を無効化して走り続ける。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 120, 2, 2.5, 0, 105, 0.014, 1, 102, 2, 122401, "太陽よりも輝く、夏海の元気娘。　持ち前の身体能力で、どんなコースも柔軟に対応し、駆け抜ける。", 3, 111);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 3, 2.5, 1, 110, 0.017, 0, 103, 3, 122501, "波打ち際に煌めく、夏海の剣士。　日々の鍛錬で鍛えた脚で、長い距離も速度を落とさず走り切る。", 2, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 4, 1.5, 0, 110, 0.016, 1, 104, 4, 107501, "海の幸に目がない、渚のお姫様。　『王家の装備』の力を解放し、障害物をものともせず前へと進む。", 3, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 5, 2.5, 0, 110, 0.014, 0, 105, 5, 107601, "海でも主さまをお世話する、白浜の巫女。精霊の力で自身を加速させ、誰よりも速くゴールを目指す。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 255, 6, 3.5, 1, 120, 0.029, 0, 106, 6, 107801, "水着姿を恥じらう、ツンデレ猫娘。お得意の魔法で、対戦相手の走りを妨害し、レースを有利に進める。", 2, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 7, 3.5, 0, 120, 0.013, 0, 107, 7, 110601, "優雅に浜を駆ける、真夏のマホ姫。しゃなりしゃなりと、雅な身のこなしで障害物を跳び越えていく。", 1, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 8, 2.5, 1, 110, 0.014, 0, 108, 8, 110401, "浜の平和を守る、真夏の狼娘。　　獣人の強靭なスタミナで、レース　後半にスパートをかける。", 2, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 9, 1.5, 0, 105, 0.012, 1, 109, 9, 110501, "浜に力強く舞う、真夏の南国娘。　レースの喧噪の中でも精神を乱さず後半に大きな捲りを見せる。", 3, 100);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 200, 10, 2.5, 0, 105, 0.014, 0, 110, 10, 115701, "浜の事件を嗅ぎ付けた、真夏の　　名探偵。高い推理力と魔法で、的確に対戦相手の走りを乱す。", 1, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 11, 2.5, 1, 105, 0.071, 0, 111, 11, 113601, "再び鎧を脱いだ、灼熱の騎士団長。実戦で培った判断力で、瞬時にバリアを展開し、障害物を無力化する。", 2, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 12, 1.5, 0, 120, 0.014, 1, 112, 12, 107901, "水が苦手な、海辺の気まぐれ猫娘。浜に現れた美少女義賊は、対戦相手のスピードを奪いとる。", 3, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 200, 13, 1.5, 0, 110, 0.022, 0, 113, 13, 108001, "バカンスも効率第一な、海の傭兵。レースでも最高効率を求め、どんな状況でも隙のない走りを見せる。", 2, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 14, 2.5, 0, 110, 0.031, 0, 114, 14, 110301, "真夏の太陽が良く似合う、海辺の　サレンママ。多才で器用、どんな　障害物もエレガントに越えていく。", 1, 108);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 15, 0.5, 0, 110, 0.036, 1, 115, 15, 107701, "海に嵐を呼ぶ夏のドジっ娘メイド。日頃から災難に慣れており、多少　のトラブルには動じたりしない。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 16, 3.5, 1, 110, 0.048, 0, 116, 16, 113101, "粋な夏を愉しむ、若夏の姉御。　　流麗な身体捌きで、始・継・終と、UBを重ねるごとに、加速する。", 2, 95);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 17, 1.5, 0, 105, 0.043, 1, 117, 17, 113301, "夏のトキメキに触れた、オタク魔法少女。多彩な魔法を操り、少しずつ他の走者の速度を落とし続ける。", 3, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 18, 1.5, 0, 105, 0.018, 1, 118, 18, 113201, "海獄に降臨せし、真夏の冥姫。　　レース後半に魔力を全解放し、　　蒼き疾風と成りて浜を駆け抜ける。", 2, 95);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 19, 2.5, 0, 110, 0.021, 0, 119, 19, 117001, "夏の夕を火花で彩る、渚の壊し屋。『壊し屋』の異名と過激な愛情は、対戦相手にプレッシャーを与える。", 2, 108);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 255, 20, 2.5, 1, 110, 0.036, 0, 120, 20, 113501, "青春に生きる者を導く、夏の先生。夢へと邁進する聖母の加護が、その身をあらゆる困難から守る。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 21, 2.5, 1, 105, 0.02, 0, 121, 21, 113401, "笑顔の応援が眩しい、夏の超能力　ガール。超能力を駆使して、どんな障害物もひとっ飛びで乗り越える。", 3, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 22, 2.5, 0, 110, 0.018, 1, 122, 22, 110101, "海辺で大人の魅力を放つ、夏の　　セクシー先生。その魅力に囚われた対戦相手は、走りを乱してしまう。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 23, 3.5, 0, 105, 0.03, 0, 123, 23, 110001, "水着も絶対外さない、夏のカリスマモデル。走りのバイブスは超テンアゲで、スピードはおにやば。", 3, 111);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 24, 1.5, 0, 110, 0.027, 1, 124, 24, 117201, "南の島も盛り上げる、真夏のアイドル。悪天候でも笑顔を絶やさず後半もリズムを上げて走り切る。", 1, 103);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 160, 25, 3.5, 0, 105, 0.02, 0, 125, 25, 117301, "海原に美声を響かす、渚の歌姫。　守護の賛歌と精霊の加護により、　障害物から身を守る。", 2, 108);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 26, 2.5, 1, 110, 0.04, 0, 126, 26, 117401, "夏でも天邪鬼な、夕凪のテーラー。張り巡らされた魔法の糸で、他の走者の自由を奪う。", 3, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 350, 27, 3.5, 1, 110, 0.009, 0, 127, 27, 117101, "向日葵が良く似合う、海辺の　　　お姉ちゃん。秘密結社の一員で、　抜群の身体能力が一番の武器。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 255, 28, 3.5, 1, 120, 0.022, 0, 128, 28, 122901, "渚でおっとり、夏色うさぎっこ。　うさぎさんパワー全開で、ぴょん　ぴょんとコースを跳ね回る。", 1, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (0, 130, 29, 2.5, 0, 110, 0.028, 1, 129, 29, 122801, "無邪気さ弾ける、夏色いたずら娘。砂浜でも、いたずらの準備は万端！レースに大波乱が巻き起こる！？", 3, 105);
INSERT INTO `v1_0a9d616381d2949a4aedd0e68ccb0c9653ecc7262bb76033dc0d435382da057e` VALUES (1, 130, 30, 3.5, 0, 105, 0.023, 0, 130, 30, 122701, "海でも真面目な、夏色優等生。　　高めた魔力を解き放ち、一瞬の内に他の走者を置き去りにする。", 2, 108);
